class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build_bst_brute(nums):
    if not nums: return None
    def helper(lo, hi):
        if lo > hi: return None
        mid = (lo + hi) // 2
        node = T(nums[mid])
        node.l = helper(lo, mid - 1)
        node.r = helper(mid + 1, hi)
        return node
    return helper(0, len(nums) - 1)

def preorder(node):
    if node is None: return []
    return [node.v] + preorder(node.l) + preorder(node.r)

