import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build_bst_best(nums):
    if not nums: return None
    root = T(nums[0])
    stack = [(root, 0, len(nums) - 1)]
    while stack:
        node, lo, hi = stack.pop()
        mid = (lo + hi) // 2
        node.v = nums[mid]
        if lo <= mid - 1:
            node.l = T(0)
            stack.append((node.l, lo, mid - 1))
        if mid + 1 <= hi:
            node.r = T(0)
            stack.append((node.r, mid + 1, hi))
    return root

def preorder(node):
    if node is None: return []
    return [node.v] + preorder(node.l) + preorder(node.r)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1+n]))
    root = build_bst_best(nums)
    print(' '.join(map(str, preorder(root))))
